const proteinOrBaseTags=new Set(['chicken','beef','pork','turkey','fish','tuna','salmon','shrimp','eggs','lentil','chickpea','beans','tofu','rice','pasta','noodles','couscous','quinoa','bread','wrap','gnocchi','oats','potato']);
const titleNeedles={onion:/oignon/,mushroom:/champignon/,broccoli:/brocoli/,zucchini:/courgett/,tomato:/tomate|bolognaise|basquaise|shakshuka/,pepper:/poivron/,carrot:/carotte/,avocado:/avocat/,spinach:/épinard/,greenbeans:/haricot/,cucumber:/concombre/,eggplant:/aubergine/,cauliflower:/chou-fleur/,peas:/petits pois/,cheese:/fromage|mozzarella|feta|carbonara|mac and cheese/,banana:/banane/,apple:/pomme/,berries:/fruits rouges/};
function recipeTags(recipe){const name=recipe[0].toLocaleLowerCase('fr');return [...new Set([...recipe[2],...Object.entries(titleNeedles).filter(([,needle])=>needle.test(name)).map(([tag])=>tag)])]}
const styleRules=[{key:'style-rice-veg',matches:r=>{const tags=recipeTags(r);return tags.includes('rice')&&(tags.some(tag=>['broccoli','zucchini','tomato','pepper','carrot','spinach','greenbeans','cucumber','eggplant','cauliflower','peas'].includes(tag))||/bowl|légumes/.test(r[0].toLocaleLowerCase('fr')))}},{key:'style-cold',matches:r=>/salade|sandwich|wrap|bagel|panini|croque|toast|poké|bento|onigiri|burger|tacos|pita|galette/i.test(r[0])},{key:'style-world',matches:r=>/curry|ramen|nouilles|udon|pad thaï|katsu|teriyaki|bibimbap|yassa|satay|couscous|paëlla/i.test(r[0])},{key:'style-soup',matches:r=>/soupe|velouté|ragoût|dahl|chili|blanquette/i.test(r[0])},{key:'style-pasta',matches:r=>/pâtes|pasta|lasagnes|gnocchi|risotto|bolognaise|carbonara|mac and cheese/i.test(r[0])}];
function coreTagsFor(recipe){const name=recipe[0].toLocaleLowerCase('fr');return recipeTags(recipe).filter(tag=>proteinOrBaseTags.has(tag)||titleNeedles[tag]?.test(name)||!flexibleIngredientTags.has(tag))}
function optionalTagsFor(recipe){const core=new Set(coreTagsFor(recipe));return recipeTags(recipe).filter(tag=>flexibleIngredientTags.has(tag)&&!core.has(tag))}
function excludedOptionalTags(recipe){return optionalTagsFor(recipe).filter(tag=>pref[tag]==='no')}
function recipeExclusionAnalysis(recipe,denied,dietForbidden){const tags=recipeTags(recipe);if(tags.some(tag=>dietForbidden.includes(tag)))return{allowed:false,reason:'régime'};if(styleRules.some(rule=>denied.includes(rule.key)&&rule.matches(recipe)))return{allowed:false,reason:'style'};const excluded=tags.filter(tag=>denied.includes(tag)),core=new Set(coreTagsFor(recipe));if(excluded.some(tag=>core.has(tag)))return{allowed:false,reason:'ingrédient principal'};const totalWeight=tags.reduce((sum,tag)=>sum+(core.has(tag)?3:1),0),excludedWeight=excluded.reduce((sum,tag)=>sum+(core.has(tag)?3:1),0),ratio=totalWeight?excludedWeight/totalWeight:0;if(ratio>=.36||(excluded.length>=2&&ratio>=.24))return{allowed:false,reason:'trop d’adaptations'};return{allowed:true,ratio,omitted:excluded}}
function recipeIsAllowed(recipe,denied,dietForbidden){return recipeExclusionAnalysis(recipe,denied,dietForbidden).allowed}
function userDietForbidden(){const diet=$('#diet')?.value;return diet==='vegetarian'?['chicken','beef','pork','turkey','fish','tuna','salmon','shrimp']:diet==='vegan'?['chicken','beef','pork','turkey','fish','tuna','salmon','shrimp','eggs','cheese','yogurt']:diet==='pescatarian'?['chicken','beef','pork','turkey']:diet==='no-pork'||diet==='halal'?['pork']:diet==='no-lactose'?['cheese','yogurt']:diet==='no-gluten'?['pasta','noodles','bread','wrap','oats']:[]}
