function recipeEquipmentGroups(recipe){if(Array.isArray(recipe._equipment)&&recipe._equipment.length)return[recipe._equipment];const name=recipe[0].toLocaleLowerCase('fr');if(/smoothie/.test(name))return[['blender']];if(/lasagnes|hachis|moussaka|quiche|muffin|gratin/.test(name))return[['oven']];if(/au four|rôti|poisson pané/.test(name))return[['oven','airfryer']];if(/salade|sandwich|wrap|bagel|panini|croque|toast|onigiri|rillettes|fromage blanc|skyr|yaourt|compote|pudding|energy balls|popcorn|edamame|roulés|œufs durs/.test(name))return[];return[['stovetop']]}
