const catalogPage=document.createElement('section');catalogPage.id='catalog';catalogPage.className='hidden';catalogPage.innerHTML='<div class="backrow"><button type="button" onclick="goHome()">⌂ Accueil</button><button type="button" onclick="suggest()">🍱 Créer mon batch</button></div><div class="catalog-hero"><h1>Nos <i>recettes.</i></h1><p>Explore librement les idées compatibles avec tes goûts. Ici, rien n’est ajouté à ton batch tant que tu ne le décides pas.</p></div><div class="catalog-controls"><input id="catalogSearch" class="catalog-search" type="search" placeholder="🔎 Chercher une recette ou un ingrédient…"><div id="catalogFilters" class="catalog-filters"><button type="button" class="on" data-filter="all">✨ Toutes</button><button type="button" data-filter="quick">⚡ Rapides</button><button type="button" data-filter="batch">🍱 Batch</button><button type="button" data-filter="sandwich">🥪 Sandwichs</button><button type="button" data-filter="breakfast">☀️ Petit-déj</button><button type="button" data-filter="light">🥗 Léger</button></div></div><p id="catalogCount" class="catalog-count"></p><div id="catalogGrid" class="catalog-grid"></div><div class="catalog-cta"><div><h2>Une recette te donne envie ?</h2><p>Crée ensuite ton batch avec les plats que tu veux vraiment manger.</p></div><button type="button" onclick="suggest()">Créer mon batch →</button></div>';
const proposalStyle=document.createElement('style');proposalStyle.textContent='.proposal-box{margin:0 0 18px;padding:20px;border-radius:25px;background:linear-gradient(135deg,#fff2b6,#ffd4ed);box-shadow:0 11px 25px rgba(145,81,31,.1)}.proposal-box h2{margin:0;color:#20386f}.proposal-box p{margin:7px 0 12px;line-height:1.4}.proposal-quick{display:flex;gap:9px;flex-wrap:wrap}.proposal-quick input,.proposal-form input,.proposal-form select,.proposal-form textarea{min-width:0;border:0;border-radius:13px;padding:11px 12px;background:#fff;color:#20386f;font:inherit}.proposal-quick input{flex:1 1 210px}.proposal-quick button,.proposal-actions button{border:0;border-radius:13px;padding:11px 14px;background:#3d16e8;color:#fff;font-weight:900;cursor:pointer}.proposal-quick button.alt,.proposal-actions button.alt{background:#e8e9f8;color:#3d16e8}.proposal-status{margin:10px 0 0;font-weight:800;color:#4f3976}.proposal-preview{display:grid;grid-template-columns:110px 1fr;gap:14px;margin-top:14px;padding:12px;border-radius:18px;background:#fff}.proposal-preview img{width:110px;height:90px;object-fit:cover;border-radius:13px}.proposal-preview h3,.proposal-preview p{margin:2px 0}.proposal-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}.proposal-form{display:grid;gap:10px;margin-top:14px;padding-top:14px;border-top:2px dashed #e2a1cc}.proposal-form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.proposal-form textarea{min-height:92px;resize:vertical}.proposal-form label{display:grid;gap:5px;font-size:13px;font-weight:900;color:#394d82}.proposal-form .proposal-save{justify-self:start;background:#20386f}.proposal-form.hidden,.proposal-preview.hidden{display:none}@media(max-width:600px){.proposal-form-grid{grid-template-columns:1fr}.proposal-preview{grid-template-columns:80px 1fr}.proposal-preview img{width:80px;height:80px}}';document.head.append(proposalStyle);
const proposalBox=document.createElement('section');proposalBox.className='proposal-box';proposalBox.innerHTML='<h2>💡 Une idée de recette ?</h2><p>Tu as vu un plat sur TikTok, chez un pote ou au resto ? Donne juste son nom : on cherche une fiche publique et son image. Tu peux aussi tout créer toi-même.</p><div class="proposal-quick"><input id="proposalQuickName" placeholder="Ex. chicken tikka masala, sandwich raclette…"><button type="button" onclick="lookupRecipeProposal()">Chercher la recette ✨</button><button type="button" class="alt" onclick="toggleRecipeForm()">Créer complètement</button></div><p id="proposalStatus" class="proposal-status"></p><div id="proposalPreview" class="proposal-preview hidden"></div><form id="proposalForm" class="proposal-form hidden"><h3>Créer ma recette</h3><label>Nom de la recette<input id="customRecipeName" required placeholder="Ex. Mon gratin de pâtes"></label><div class="proposal-form-grid"><label>Moment<select id="customRecipeMeal"><option value="dinner">Soir</option><option value="lunch">Midi</option><option value="breakfast">Petit-déj</option><option value="snack">Collation</option></select></label><label>Kcal / portion<input id="customRecipeKcal" type="number" value="550"></label><label>Protéines / portion<input id="customRecipeProtein" type="number" value="30"></label></div><div class="proposal-form-grid"><label>Coût estimé du batch (4 portions)<input id="customRecipeCost" type="number" value="10"></label><label>Matériel<select id="customRecipeEquipment"><option value="stovetop">Plaques</option><option value="microwave">Micro-ondes</option><option value="airfryer">Air fryer</option><option value="oven">Four</option><option value="">Sans cuisson</option></select></label><label>URL de l’image (optionnel)<input id="customRecipeImage" placeholder="https://…"></label></div><label>Ingrédients — une ligne par ingrédient<textarea id="customRecipeIngredients" required placeholder="600 g de poulet&#10;300 g de riz&#10;…"></textarea></label><label>Étapes — une ligne par étape<textarea id="customRecipeSteps" required placeholder="1. Faire cuire le riz…&#10;2. …"></textarea></label><button class="proposal-save" type="submit">Ajouter à ma bibliothèque →</button></form>';catalogPage.querySelector('.catalog-hero').after(proposalBox);
