let catalogFilter='all';
function catalogMatches(recipe){const name=recipe[0].toLocaleLowerCase('fr'),tags=recipeTags(recipe);if(catalogFilter==='quick')return recipeMinutes(recipe)<=20;if(catalogFilter==='batch')return !['breakfast','snack'].includes(recipe[1])&&recipeMinutes(recipe)<=45;if(catalogFilter==='sandwich')return /sandwich|wrap|bagel|panini|croque|toast|burger|tacos|pita|banh mi/.test(name);if(catalogFilter==='breakfast')return recipe[1]==='breakfast';if(catalogFilter==='light')return Number(recipe[3])<=520||tags.includes('salade');return true}
function renderCatalog(){const query=$('#catalogSearch').value.trim().toLocaleLowerCase('fr'),denied=Object.keys(pref).filter(key=>pref[key]==='no'),dietForbidden=userDietForbidden(),visible=recipes.filter(recipe=>recipeIsAllowed(recipe,denied,dietForbidden)&&recipeEquipmentCompatible(recipe)&&catalogMatches(recipe)&&(recipe[0].toLocaleLowerCase('fr').includes(query)||recipeTags(recipe).some(tag=>foodLabelByTag[tag]?.toLocaleLowerCase('fr').includes(query))));$('#catalogCount').textContent=`${visible.length} recette${visible.length>1?'s':''} compatible${visible.length>1?'s':''} avec ton profil et ton équipement`;$('#catalogGrid').innerHTML=visible.map(recipe=>{const source=recipeImage(recipe),fallback=recipeFallback(recipe),meal={breakfast:'☀️ Petit-déj',lunch:'🥗 Midi',dinner:'🍽️ Plat',snack:'🍏 Collation'}[recipe[1]]||'🍽️ Plat',index=recipes.indexOf(recipe);return `<article class="catalog-recipe"><img src="${source}" onerror="this.onerror=null;this.src='${fallback}'" alt="${recipe[0]}"><div><small class="catalog-badge">${meal} · ~${recipeMinutes(recipe)} min</small><b>${recipe[0]}</b><small>${recipe[3]} kcal · ${recipe[4]} g protéines</small><small>${recipePriceLabel(recipe)}</small><small>${recipeEquipmentText(recipe)}</small>${recipeAdaptation(recipe)?`<small>⚠️ ${recipeAdaptation(recipe)}</small>`:''}<button type="button" class="recipe-info" data-recipe-index="${index}">Voir la recette ↗</button></div></article>`}).join('')||'<p class="note">Aucune recette ne correspond. Essaie un autre filtre ou ajoute un équipement.</p>';$('#catalogGrid').querySelectorAll('.recipe-info').forEach(button=>button.onclick=()=>openRecipeModal(recipes[Number(button.dataset.recipeIndex)]))}
function inferCustomTags(text){const value=String(text).toLocaleLowerCase('fr'),pairs=[['poulet','chicken'],['chicken','chicken'],['boeuf','beef'],['bœuf','beef'],['dinde','turkey'],['thon','tuna'],['saumon','salmon'],['crevette','shrimp'],['poisson','fish'],['oeuf','eggs'],['œuf','eggs'],['lentille','lentil'],['pois chiche','chickpea'],['tofu','tofu'],['riz','rice'],['pâte','pasta'],['nouille','noodles'],['semoule','couscous'],['quinoa','quinoa'],['pain','bread'],['wrap','wrap'],['pomme de terre','potato'],['tomate','tomato'],['oignon','onion'],['brocoli','broccoli'],['courgette','zucchini'],['poivron','pepper'],['carotte','carrot'],['champignon','mushroom'],['épinard','spinach'],['fromage','cheese'],['skyr','yogurt'],['yaourt','yogurt'],['coco','coconut'],['banane','banana'],['pomme','apple']];return [...new Set(pairs.filter(([needle])=>value.includes(needle)).map(([,tag])=>tag))]}
function customRow(record){const row=[record.name,record.meal||'dinner',record.tags||[],Number(record.kcal)||500,Number(record.protein)||25,Number(record.cost)||10];row._id=record.id;row._image=record.image;row._ingredients=record.ingredients;row._steps=record.steps;row._equipment=record.equipment;row._source=record.source;return row}
async function loadCustomRecipes(){try{const stored=await fetch('/api/recipes').then(response=>response.json());(stored||[]).map(customRow).filter(row=>!recipes.some(recipe=>recipe._id===row._id||recipe[0]===row[0])).forEach(row=>recipes.push(row));if(!$('#catalog').classList.contains('hidden'))renderCatalog()}catch{}}
window.toggleRecipeForm=()=>{$('#proposalForm').classList.toggle('hidden');$('#proposalForm').scrollIntoView({behavior:'smooth',block:'nearest'})};
function showProposalDraft(draft){const preview=$('#proposalPreview');window.recipeProposalDraft={...draft,tags:inferCustomTags(`${draft.name} ${(draft.ingredients||[]).join(' ')}`)};preview.innerHTML=`<img src="${draft.image||'/assets/batch-meals-mosaic-v1.png'}" alt="${draft.name}"><div><h3>${draft.name}</h3><p>${draft.ingredients?.length||0} ingrédients et ${draft.steps?.length||0} étapes trouvés. Vérifie avant d’ajouter : la fiche vient d’une source publique.</p><div class="proposal-actions"><button type="button" onclick="saveRecipeProposal()">Ajouter à ma bibliothèque</button><button type="button" class="alt" onclick="fillRecipeFormFromDraft()">Modifier avant d’ajouter</button></div></div>`;preview.classList.remove('hidden')}
window.lookupRecipeProposal=async()=>{const name=$('#proposalQuickName').value.trim(),status=$('#proposalStatus'),preview=$('#proposalPreview');if(!name){status.textContent='Écris le nom du plat que tu veux proposer.';return}status.textContent='Recherche d’idées proches, d’une fiche et d’une photo…';preview.classList.add('hidden');try{const response=await fetch(`/api/recipe-suggest?name=${encodeURIComponent(name)}`);if(!response.ok)throw new Error();const data=await response.json(),candidates=data.candidates||[];if(!candidates.length)throw new Error();window.recipeProposalCandidates=candidates;if(candidates.length===1){showProposalDraft(candidates[0]);status.textContent='Fiche trouvée : tu peux l’ajouter ou la modifier.';return}preview.innerHTML=`<div style="grid-column:1/-1"><h3>Des idées proches de « ${name} »</h3><p>Choisis celle qui ressemble le plus à ton idée ; tu pourras modifier la fiche ensuite.</p><div class="proposal-actions">${candidates.map((draft,index)=>`<button type="button" class="alt" onclick="chooseRecipeProposal(${index})">${draft.name}</button>`).join('')}</div></div>`;preview.classList.remove('hidden');status.textContent=`${candidates.length} idées proches trouvées — pas besoin du nom exact.`}catch{status.textContent='Aucune idée proche trouvée. Tu peux la créer complètement juste dessous.';$('#proposalForm').classList.remove('hidden');$('#customRecipeName').value=name}};
window.chooseRecipeProposal=index=>{const draft=window.recipeProposalCandidates?.[index];if(draft)showProposalDraft(draft)};
window.fillRecipeFormFromDraft=()=>{const draft=window.recipeProposalDraft;if(!draft)return;$('#proposalForm').classList.remove('hidden');$('#customRecipeName').value=draft.name||'';$('#customRecipeImage').value=draft.image||'';$('#customRecipeIngredients').value=(draft.ingredients||[]).join('\n');$('#customRecipeSteps').value=(draft.steps||[]).join('\n');$('#proposalForm').scrollIntoView({behavior:'smooth',block:'nearest'})};
async function saveCustomRecipe(payload){const response=await fetch('/api/recipes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error();const saved=await response.json(),row=customRow(saved);if(!recipes.some(recipe=>recipe._id===row._id))recipes.unshift(row);renderCatalog();$('#proposalStatus').textContent=`✓ « ${saved.name} » est ajoutée à ta bibliothèque.`;$('#proposalPreview').classList.add('hidden');$('#proposalForm').classList.add('hidden');return saved}
window.saveRecipeProposal=async()=>{const draft=window.recipeProposalDraft;if(!draft)return;try{await saveCustomRecipe({...draft,tags:draft.tags||inferCustomTags(`${draft.name} ${(draft.ingredients||[]).join(' ')}`),kcal:500,protein:25,cost:10,equipment:['stovetop']})}catch{$('#proposalStatus').textContent='Impossible d’ajouter la recette pour le moment.'}};
$('#proposalForm').addEventListener('submit',async event=>{event.preventDefault();const name=$('#customRecipeName').value.trim(),ingredients=$('#customRecipeIngredients').value.split('\n').map(line=>line.trim()).filter(Boolean),steps=$('#customRecipeSteps').value.split('\n').map(line=>line.replace(/^\d+[.)]\s*/, '').trim()).filter(Boolean),equipment=$('#customRecipeEquipment').value;if(!name||!ingredients.length||!steps.length){$('#proposalStatus').textContent='Ajoute au moins un ingrédient et une étape.';return}try{await saveCustomRecipe({name,meal:$('#customRecipeMeal').value,kcal:+$('#customRecipeKcal').value,protein:+$('#customRecipeProtein').value,cost:+$('#customRecipeCost').value,image:$('#customRecipeImage').value.trim(),ingredients,steps,tags:inferCustomTags(`${name} ${ingredients.join(' ')}`),equipment:equipment?[equipment]:[],source:'Proposée par toi'});event.target.reset()}catch{$('#proposalStatus').textContent='Impossible d’ajouter la recette pour le moment.'}});
$('#catalogSearch').addEventListener('input',renderCatalog);$('#catalogFilters').querySelectorAll('button').forEach(button=>button.onclick=()=>{catalogFilter=button.dataset.filter;$('#catalogFilters').querySelectorAll('button').forEach(item=>item.classList.toggle('on',item===button));renderCatalog()});
const fridgeColours=['#ff9d78','#f8d857','#b9f35d','#c7b2ff','#8ed6ff','#ffb1cd'];
window.fridgeItems=[];
async function renderFridge(){try{const items=await fetch('/api/fridge').then(response=>response.json());window.fridgeItems=Array.isArray(items)?items:[];const active=window.fridgeItems.filter(item=>Number(item.remaining)>0);const total=active.reduce((sum,item)=>sum+Number(item.remaining||0),0);$('#fridgeKpi').textContent=`🍱 ${total} repas restant${total>1?'s':''}`;if(!active.length){$('#fridgeContent').innerHTML='<div class="fridge-empty"><h2>Ton frigo est prêt.</h2><p>Ton prochain batch le remplira de vrais tuppers. Ensuite, un clic suffit pour signaler que tu as mangé une portion.</p><button class="primary" type="button" onclick="goRecipes()">Choisir mon batch →</button></div>';return}$('#fridgeContent').innerHTML=`<div class="fridge-shell"><div class="fridge-door">${active.map((item,index)=>{const recipe=recipes.find(row=>row[0]===item.recipeName),total=Number(item.total||4),remaining=Number(item.remaining||0),fresh=Math.min(Number(item.fresh||0),remaining),frozen=Math.min(Number(item.frozen||0),Math.max(0,remaining-fresh)),colour=fridgeColours[index%fridgeColours.length],photo=recipe?recipeImage(recipe):recipeFallback([item.recipeName]),fallback=recipe?recipeFallback(recipe):'',tuples=Array.from({length:total},(_,slot)=>`<span class="tupper ${slot<fresh?'full':slot<fresh+frozen?'full frozen':''}" style="--meal:${colour}" title="${slot<remaining?'Portion disponible':'Déjà mangée'}"></span>`).join('');return `<article class="fridge-shelf"><div class="fridge-meal"><img class="fridge-photo" src="${photo}" onerror="this.onerror=null;this.src='${fallback}'" alt="${item.recipeName}"><div class="fridge-main"><div class="fridge-row-head"><h3><span class="meal-dot" style="--meal:${colour}"></span>${item.recipeName}</h3><small>${remaining} / ${total}</small></div><div class="tupper-grid" aria-label="${remaining} portions restantes sur ${total}">${tuples}</div><div class="fridge-actions"><small>🧊 ${frozen} congélo · ❄️ ${fresh} frais</small><button type="button" onclick="eatFridgePortion('${item.id}')">J’ai mangé 1</button></div></div></div></article>`}).join('')}</div></div><p class="fridge-help">Astuce : commence par les portions au frais. L’app utilise ensuite automatiquement celles du congélateur.</p>`}catch{$('#fridgeContent').innerHTML='<div class="fridge-empty">Impossible de charger ton frigo pour le moment.</div>'}}
window.eatFridgePortion=async id=>{const item=window.fridgeItems.find(row=>row.id===id);if(!item||Number(item.remaining)<=0)return;const fresh=Math.max(0,Number(item.fresh||0)-(Number(item.fresh||0)>0?1:0));const frozen=Math.max(0,Number(item.frozen||0)-(Number(item.fresh||0)>0?0:1));await fetch(`/api/fridge/${id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({remaining:Math.max(0,Number(item.remaining)-1),fresh,frozen})});void renderFridge()};
const homeStyle=document.createElement('style');homeStyle.textContent='.home-dash{margin:0 0 24px;padding:23px;border-radius:29px;background:linear-gradient(135deg,#3d16e8,#6f41ff);color:#fff;overflow:hidden;position:relative;box-shadow:0 16px 35px rgba(61,22,232,.25)}.home-dash:after{content:"";position:absolute;width:230px;height:230px;right:-70px;bottom:-140px;border:25px solid rgba(255,255,255,.13);border-radius:48%;transform:rotate(25deg)}.home-dash>*{position:relative;z-index:1}.home-dash h2{font-size:31px;margin:0 0 5px;color:#fff}.home-dash p{margin:0;color:#e6e1ff}.home-progress{margin:17px 0 12px;padding:14px;background:rgba(255,255,255,.16);border-radius:17px}.home-progress-top{display:flex;justify-content:space-between;gap:10px;font-weight:900}.home-track{height:12px;margin-top:10px;border-radius:99px;background:rgba(255,255,255,.3);overflow:hidden}.home-track span{display:block;height:100%;border-radius:inherit;background:#f8d857}.home-kpis{display:flex;gap:10px;flex-wrap:wrap}.home-kpi{min-width:120px;flex:1;padding:11px 13px;border-radius:16px;background:#fff;color:#172d27;font-weight:900}.home-kpi small{display:block;font-weight:600;color:#596b66;margin-top:2px}.home-dash button{margin-top:16px;border:0;border-radius:15px;background:#f8d857;color:#172d27;padding:12px 17px;font-weight:900;cursor:pointer}.home-dash button:hover{background:#fff}.home-disclaimer{display:block;margin-top:9px;color:#d8d0ff;font-size:11px}@media(max-width:700px){.home-dash{padding:18px;border-radius:21px}.home-dash h2{font-size:27px}.home-kpis{gap:7px}.home-kpi{min-width:96px;font-size:14px}}';document.head.append(homeStyle);
const homeDash=document.createElement('section');homeDash.id='homeDash';homeDash.className='home-dash';$('#setup').prepend(homeDash);
async function renderHomeDashboard(){try{const [state,fridge]=await Promise.all([fetch('/api/me').then(response=>response.json()),fetch('/api/fridge').then(response=>response.json())]);const plans=state.history||[],remaining=(fridge||[]).reduce((sum,item)=>sum+Number(item.remaining||0),0),monthPlans=plans.filter(plan=>new Date(plan.createdAt).getMonth()===new Date().getMonth()).length,progress=Math.min(100,monthPlans/4*100),groupedMinutes=plans.length*75,groupedHours=`${Math.floor(groupedMinutes/60)}h${String(groupedMinutes%60).padStart(2,'0')}`,objectiveCount=Math.min(monthPlans,4);$('#homeDash').innerHTML=`<h2>Hey 👋 On cuisine ?</h2><p>Moins de prises de tête, plus de repas prêts quand tu rentres.</p><div class="home-progress"><div class="home-progress-top"><span>Objectif du mois</span><span>${objectiveCount}/4 batchs</span></div><div class="home-track"><span style="width:${progress}%"></span></div></div><div class="home-kpis"><div class="home-kpi">🍱 ${remaining}<small>repas prêts à manger</small></div><div class="home-kpi">⏱️ ${groupedHours}<small>de cuisine regroupée</small></div><div class="home-kpi">💶 Budget suivi<small>tes courses en un coup d’œil</small></div></div><button type="button" onclick="suggest()">Créer mon batch →</button>`}catch{$('#homeDash').innerHTML='<h2>Hey 👋 On cuisine ?</h2><p>Crée ton premier batch, choisis tes recettes et remplis ton frigo.</p><button type="button" onclick="suggest()">Commencer →</button>'}}
function formatProfileDate(value){try{return new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value))}catch{return 'Date inconnue'}}
async function renderProfilePage(){try{const state=await fetch('/api/me').then(response=>response.json());const profile=state.profile||{},plans=state.history||[],measurements=state.measurements||[];const goalLabels={loss:'Perdre du poids',maintain:'Maintenir mon poids',gain:'Prise de masse'};$('#profileSummary').innerHTML=`<h2>${goalLabels[profile.goal]||'Mon objectif'}</h2><p><b>${profile.weight||'—'} kg</b> · ${profile.height||'—'} cm · ${profile.age||'—'} ans · ${profile.store||'Supermarché à choisir'}</p><p>Repères actuels : <b>${calorieTarget()} kcal/jour</b> · <b>${proteinTarget()} g de protéines/jour</b>.</p>`;$('#profileRewards').innerHTML=`<div class="reward-grid"><div class="reward ${plans.length?'':'locked'}">🍱 Premier batch<small>${plans.length?'Débloqué':'Crée ton premier batch'}</small></div><div class="reward ${plans.length>=4?'':'locked'}">🏅 Cuisinier régulier<small>${Math.min(plans.length,4)} / 4 batchs</small></div><div class="reward ${measurements.length>=2?'':'locked'}">📈 Suivi lancé<small>${measurements.length>=2?'Tes pesées évoluent':'Ajoute 2 pesées'}</small></div></div>`;const ordered=[...measurements].reverse();if(!ordered.length){$('#weightHistory').innerHTML='<p class="profile-empty">Ajoute une pesée depuis la carte verte pour voir ton évolution.</p>'}else{const values=ordered.map(row=>Number(row.weight)).filter(Number.isFinite),min=Math.min(...values),max=Math.max(...values),span=Math.max(max-min,1);$('#weightHistory').innerHTML=`<div class="weight-chart">${ordered.slice(-12).map(row=>{const value=Number(row.weight),height=28+((value-min)/span)*62;return `<div class="weight-bar" style="height:${height}%"><span>${value} kg</span></div>`}).join('')}</div><p><small>De ${formatProfileDate(ordered[0].createdAt)} à ${formatProfileDate(ordered.at(-1).createdAt)} · ${values.length} pesée${values.length>1?'s':''}</small></p>`}$('#batchHistory').innerHTML=plans.length?`<div class="profile-list">${plans.slice(0,8).map(plan=>`<div class="history-row"><b>${formatProfileDate(plan.createdAt)} · ${(Number(plan.estimatedTotal)||0).toFixed(2).replace('.',',')} €</b><small>${(plan.recipeNames||[]).join(' · ')||'Batch enregistré'} · ${plan.store||'Magasin non renseigné'}</small></div>`).join('')}</div>`:'<p class="profile-empty">Ton historique apparaîtra après ton premier panier.</p>'}catch{$('#profileSummary').innerHTML='<p class="profile-empty">Impossible de charger ton historique pour le moment.</p>'}}
Object.entries(foodGroups).forEach(([title, foods]) => { const group=document.createElement('section'); group.className='category'; group.innerHTML=`<h3>${title}</h3><div class="chips"></div>`; foods.forEach(([emoji,name,key])=>{const b=document.createElement('button');b.className='chip';b.textContent=`${emoji} ${name}`;b.classList.toggle('love',pref[key]==='love');b.classList.toggle('no',pref[key]==='no');b.title=pref[key]==='no'?'Exclu':pref[key]==='love'?'J’adore':'J’accepte';b.onclick=()=>{pref[key]=pref[key]==='ok'?'love':pref[key]==='love'?'no':'ok';b.classList.toggle('love',pref[key]==='love');b.classList.toggle('no',pref[key]==='no');b.title=pref[key]==='no'?'Exclu':pref[key]==='love'?'J’adore':'J’accepte'};group.querySelector('.chips').append(b)});$('#foods').append(group)});
$('#foods').addEventListener('click',()=>setTimeout(()=>localStorage.setItem('batch-preferences',JSON.stringify(pref)),0));
function calorieTarget(){const weight=Number($('#weight').value),height=Number($('#height').value),age=Number($('#age').value);if(!weight||!height||!age)return '—';const adjustment=$('#sex')?.value==='female'?-161:5;const base=(10*weight+6.25*height-5*age+adjustment)*({low:1.25,medium:1.45,high:1.65}[$('#activity').value]);return Math.round((base+($('#goal').value==='loss'?-450:$('#goal').value==='gain'?280:0))/50)*50}
function meals(){return [...document.querySelectorAll('.mealrow input:checked')].map(x=>x.value)}
function recipeFitness(recipe){const shares={breakfast:.23,lunch:.31,dinner:.34,snack:.12};const ideal=(Number(calorieTarget())||2000)*(shares[recipe[1]]||.25);const kcalPenalty=Math.abs(recipe[3]-ideal)*.28;const proteinNeed=$('#goal').value==='gain'?34:$('#goal').value==='loss'?30:26;const proteinBonus=Math.min(recipe[4],proteinNeed)*3;const loveBonus=recipeTags(recipe).filter(tag=>pref[tag]==='love').length*90;const styleLoveBonus=styleRules.filter(rule=>pref[rule.key]==='love'&&rule.matches(recipe)).length*70;return loveBonus+styleLoveBonus+proteinBonus-kcalPenalty}
function recipeFamily(recipe){const name=recipe[0].toLocaleLowerCase('fr');if(/sandwich|wrap|bagel|panini|croque|toast|burger|tacos|pita|banh mi/.test(name))return 'sandwich';if(/curry|ramen|nouilles|udon|pad thaï|katsu|teriyaki|bibimbap|yassa/.test(name))return 'monde';if(/pâtes|pasta|lasagnes|gnocchi|risotto|bolognaise/.test(name))return 'italien';if(/salade|bowl|poké|bento|taboulé|quinoa/.test(name))return 'frais';if(recipe[1]==='breakfast')return 'petit-déj';if(recipe[1]==='snack')return 'collation';return 'classique'}
function recipeMinutes(recipe){const name=recipe[0].toLocaleLowerCase('fr');return /sandwich|wrap|bagel|panini|croque|salade|poké|bowl|bento|toast|onigiri|burger|tacos|galette/i.test(name)?15:recipe[1]==='breakfast'||recipe[1]==='snack'?12:30}
function recipePriceLabel(recipe){const batch=Number(recipe[5])||0,portion=batch/4;return `env. ${batch.toFixed(0)} € le batch (4 portions) · ${portion.toFixed(2).replace('.',',')} € / portion`}
function recipeCardMarkup(r,featured=false){const source=recipeImage(r),fallback=recipeFallback(r),adaptation=recipeAdaptation(r),credit=sourcedRecipePhotos[r[0]]?.credit,index=recipes.indexOf(r);return `<article class="recipe ${selected.has(r[0])?'sel':''}" data-name="${r[0]}"><img src="${source}" onerror="this.onerror=null;this.src='${fallback}'" alt="Illustration de ${r[0]}"><div>${featured?`<span class="featured-label">${featured==='discovery'?'🌈 Découverte compatible':'✓ Fait pour toi'} · ~${recipeMinutes(r)} min</span>`:''}<b>${r[0]}</b><small>${r[3]} kcal indicatives · ${r[4]} g protéines</small><small>${recipePriceLabel(r)}</small>${adaptation?`<strong class="adaptation">⚠️ ${adaptation}</strong>`:''}<button class="recipe-info" type="button" data-recipe-index="${index}">Voir la recette ↗</button>${credit?`<small class="photo-credit">${credit}</small>`:''}</div></article>`}
function bindRecipeCards(root){root.querySelectorAll('.recipe').forEach(card=>card.onclick=event=>{if(event.target.closest('.recipe-info'))return;const target=batchRecipeCount();if(selected.has(card.dataset.name))selected.delete(card.dataset.name);else if(selected.size<target)selected.add(card.dataset.name);else{$('#selectedCount').textContent=`${target} / ${target} recette${target>1?'s':''} : retire un plat avant d’en choisir un autre.`;return}updateSelectionCount();renderRecipeSections()});root.querySelectorAll('.recipe-info').forEach(button=>button.onclick=event=>{event.stopPropagation();openRecipeModal(recipes[Number(button.dataset.recipeIndex)])})}
function renderRecipeCards(list,root=$('#recipes'),featured=false){root.innerHTML=list.map(recipe=>recipeCardMarkup(recipe,featured&&recipe[0]===window.discoveryRecipeName?'discovery':featured)).join('')||'<p class="note">Aucune recette ne correspond à cette recherche.</p>';bindRecipeCards(root)}
function matchesExploreFilter(recipe){const name=recipe[0].toLocaleLowerCase('fr'),tags=recipeTags(recipe);if(exploreFilter==='quick')return recipeMinutes(recipe)<=20;if(exploreFilter==='batch')return !['breakfast','snack'].includes(recipe[1])&&recipeMinutes(recipe)<=45;if(exploreFilter==='sandwich')return /sandwich|wrap|bagel|panini|croque|toast|burger|tacos|pita|banh mi/.test(name);if(exploreFilter==='light')return Number(recipe[3])<=520||tags.includes('salade');return true}
function renderRecipeSections(){const all=window.currentProposed||[],query=recipeSearch.value.trim().toLocaleLowerCase('fr');renderRecipeCards(window.recommendedRecipes||[],$('#recommendedRecipes'),'featured');renderRecipeCards(all.filter(recipe=>recipe[0].toLocaleLowerCase('fr').includes(query)&&matchesExploreFilter(recipe)))}
recipeSearch.addEventListener('input',renderRecipeSections);
function suggest(){
 const denied=Object.keys(pref).filter(key=>pref[key]==='no');
 const diet=$('#diet').value;
 const dietForbidden=diet==='vegetarian'?['chicken','beef','pork','turkey','fish','tuna','salmon','shrimp']:diet==='vegan'?['chicken','beef','pork','turkey','fish','tuna','salmon','shrimp','eggs','cheese','yogurt']:diet==='pescatarian'?['chicken','beef','pork','turkey']:diet==='no-pork'||diet==='halal'?['pork']:diet==='no-lactose'?['cheese','yogurt']:diet==='no-gluten'?['pasta','noodles','bread','wrap','oats']:[];
 const proposed=recipes.filter(r=>meals().includes(r[1])&&recipeIsAllowed(r,denied,dietForbidden)&&recipeEquipmentCompatible(r)).sort((a,b)=>recipeFitness(b)-recipeFitness(a)||Math.random()-.5);
 selected.clear();const families=new Set(),target=batchRecipeCount();for(const recipe of proposed){const family=recipeFamily(recipe);if(selected.size<target&&!families.has(family)){selected.add(recipe[0]);families.add(family)}}for(const recipe of proposed){if(selected.size<target)selected.add(recipe[0])}updateSelectionCount();
 $('#target').textContent=`Cible indicative : ${calorieTarget()} kcal/jour · ${proposed.length} recettes réellement compatibles. Analyse active : un ingrédient principal, un style exclu ou trop d’adaptations retire la recette. Je te pré-sélectionne ${target} gros plat${target>1?'s':''} varié${target>1?'s':''}, à répartir dans ${batchPortionCount()} tupperwares.`;
 const recommended=[],recommendationFamilies=new Set();for(const recipe of proposed){if(recommended.length>=6)break;const family=recipeFamily(recipe);if(!recommendationFamilies.has(family)){recommended.push(recipe);recommendationFamilies.add(family)}}const discovery=proposed.slice(12).find(recipe=>!recommended.includes(recipe));if(discovery)recommended.push(discovery);window.discoveryRecipeName=discovery?.[0]||null;window.currentProposed=proposed;window.recommendedRecipes=recommended;recipeSearch.value='';renderRecipeSections();
 showScreen('choices');
}
function buildLegacy(){const picked=recipes.filter(r=>selected.has(r[0]));const factor={Lidl:.86,'E.Leclerc':.95,Intermarché:1,Carrefour:1.08}[$('#store').value];const total=picked.reduce((sum,r)=>sum+r[5],0)*factor;$('#schedule').innerHTML=picked.map((r,i)=>`<div class="day"><b>${i<2?'Lundi–Mercredi':'Jeudi–Dimanche'}</b><br>${r[0]} · ${i<2?'à manger frais':'à congeler dimanche'}</div>`).join('');$('#cart').innerHTML=picked.map(r=>`<div class="day">☐ Ingrédients pour ${r[0]} <span class="price">${(r[5]*factor).toFixed(2).replace('.',',')} €</span></div>`).join('')+`<p class="total">Total estimé : ${total.toFixed(2).replace('.',',')} €</p><p>${total>+$('#budget').value?'⚠️ Dépasse ton budget : retire une recette ou sélectionne Lidl.':'✓ Dans ton budget.'}</p>`;$('#choices').classList.add('hidden');$('#final').classList.remove('hidden')}
