function recipeGuide(recipe){const [name,meal]=recipe,tags=recipeTags(recipe);const omitted=excludedOptionalTags(recipe);const ingredientNames=tags.filter(tag=>!omitted.includes(tag)).map(tag=>ingredientMap[tag]?.[0]).filter(Boolean).join(', ');const cold=/sandwich|wrap|bagel|panini|croque|salade|poké|bowl|bento|toast|onigiri|burger|tacos|galette/i.test(name);const sweet=meal==='breakfast'||meal==='snack';const minutes=cold?15:sweet?12:30;const method=cold?'Prépare les éléments, garde la sauce à part, puis assemble au dernier moment.':sweet?'Prépare en portions individuelles ; conserve au frais (ou prépare la veille pour les overnight/porridge).':'Fais cuire le féculent, saisis la protéine, ajoute les légumes et l’assaisonnement. Répartis ensuite en 4 boîtes.';const storage=cold?'2 jours au frais, ne pas congeler.':sweet?'3 jours au frais selon les ingrédients.':'3 jours au frais ; congèle les portions prévues pour la fin de semaine.';return `<details class="guide"><summary>🍳 Fiche rapide · ${minutes} min · 4 portions</summary><p><b>Base :</b> ${ingredientNames||'ingrédients indiqués dans la liste de courses'}.</p>${omitted.length?`<p><b>Adaptation :</b> sans ${omitted.map(tag=>foodLabelByTag[tag]||tag).join(', ')}.</p>`:''}<p><b>Étapes :</b> ${method}</p><p><b>Conservation :</b> ${storage}</p></details>`}
