function recipeSummary(recipe){const name=recipe[0].toLocaleLowerCase('fr'),withoutNuts=excludedOptionalTags(recipe).includes('nuts');if(/satay/.test(name))return withoutNuts?'Un plat inspiré de l’Asie du Sud-Est : du poulet et des nouilles avec une sauce crémeuse façon satay, adaptée sans cacahuètes.':'Un plat inspiré de l’Asie du Sud-Est : du poulet avec une sauce crémeuse aux cacahuètes, servi avec un féculent et des légumes.';if(/katsu/.test(name))return 'Un curry japonais doux et réconfortant, habituellement servi avec du poulet et du riz.';if(/golden curry|curry/.test(name))return 'Un plat parfumé, à la sauce épicée douce et crémeuse, pratique à cuisiner en grande quantité.';if(/ramen|nouilles|udon|pad thaï/.test(name))return 'Un plat de nouilles généreux, avec une sauce et une garniture chaude.';if(/sandwich|wrap|bagel|panini|croque|toast|burger|tacos|pita|galette/.test(name))return 'Un repas facile à emporter : une garniture complète dans du pain, une galette ou un wrap.';if(/salade|bowl|poké|bento|taboulé/.test(name))return 'Un repas frais et complet, composé autour d’une base de féculent, de légumes et d’une protéine.';if(/pâtes|pasta|lasagnes|gnocchi|risotto|bolognaise|carbonara/.test(name))return 'Un plat généreux d’inspiration italienne, idéal pour préparer plusieurs portions à l’avance.';if(recipe[1]==='breakfast')return 'Une option simple pour démarrer la journée, pensée pour être préparée vite ou à l’avance.';if(recipe[1]==='snack')return 'Une petite collation pratique pour éviter les fringales entre deux repas.';return 'Un plat complet pensé pour être cuisiné en une fois puis réparti dans tes tuppers.'}
const cookingAmounts={chicken:'600 g de poulet',beef:'500 g de bœuf haché',pork:'450 g de porc ou jambon',turkey:'550 g de dinde',fish:'600 g de poisson',tuna:'3 boîtes de thon',salmon:'500 g de saumon',shrimp:'450 g de crevettes',eggs:'6 œufs',lentil:'300 g de lentilles',chickpea:'2 boîtes de pois chiches',beans:'2 boîtes de haricots rouges',tofu:'500 g de tofu',rice:'300 g de riz',pasta:'350 g de pâtes',noodles:'300 g de nouilles',couscous:'300 g de semoule',quinoa:'280 g de quinoa',bread:'8 tranches de pain',wrap:'4 grands wraps',gnocchi:'500 g de gnocchis',oats:'240 g de flocons d’avoine',potato:'800 g de pommes de terre',broccoli:'1 gros brocoli',zucchini:'2 courgettes',tomato:'500 g de tomates ou coulis',pepper:'2 poivrons',onion:'1 gros oignon',mushroom:'400 g de champignons',carrot:'3 carottes',spinach:'250 g d’épinards',greenbeans:'500 g de haricots verts',cucumber:'1 concombre',avocado:'2 avocats',eggplant:'2 aubergines',cauliflower:'1 chou-fleur',peas:'300 g de petits pois',cheese:'150 g de fromage',yogurt:'500 g de skyr / yaourt grec',coconut:'40 cl de lait de coco',banana:'4 bananes',apple:'4 pommes',berries:'300 g de fruits rouges',nuts:'80 g de fruits à coque',spicy:'1 c. à café d’épices'};
function recipeFlavorLines(recipe,omitted){const name=recipe[0].toLocaleLowerCase('fr'),withoutNuts=omitted.includes('nuts');if(/satay/.test(name))return withoutNuts?['3 c. à soupe de sauce soja','15 cl de lait de coco','1 c. à café de miel ou sucre']:['3 c. à soupe de beurre de cacahuète ou sauce satay','2 c. à soupe de sauce soja','15 cl de lait de coco'];if(/katsu|golden curry/.test(name))return ['1 bloc de Golden Curry ou 3 c. à soupe de sauce curry japonaise','50 cl d’eau chaude'];if(/curry|tikka|teriyaki|yassa|aigre-doux|pad thaï|ramen|udon|nouilles/.test(name))return [/teriyaki/.test(name)?'4 c. à soupe de sauce teriyaki':/yassa/.test(name)?'2 c. à soupe de moutarde + jus d’un citron':/aigre-doux/.test(name)?'4 c. à soupe de sauce aigre-douce':/ramen|udon/.test(name)?'70 cl de bouillon + 2 c. à soupe de sauce soja':/nouilles|pad thaï/.test(name)?'4 c. à soupe de sauce soja':'2 c. à soupe de curry + 20 cl de lait de coco'];if(/bolognaise|tomate|basquaise|chili|shakshuka|minestrone|parmigiana/.test(name))return ['400 g de coulis de tomate','1 gousse d’ail','1 c. à café d’herbes ou paprika'];if(/pesto/.test(name))return ['4 c. à soupe de pesto','1 gousse d’ail'];if(/moutarde|stroganoff|blanquette/.test(name))return ['2 c. à soupe de moutarde','20 cl de crème ou yaourt'];if(/césar|tzatziki|grecque|niçoise|salade|poké|bowl|taboulé/.test(name))return ['3 c. à soupe de sauce ou vinaigrette','1 c. à soupe d’huile d’olive'];if(/sandwich|wrap|bagel|panini|croque|burger|tacos|pita|galette/.test(name))return ['4 c. à soupe de sauce (yaourt, moutarde ou mayonnaise)','1 c. à soupe d’huile'];if(recipe[1]==='breakfast'||recipe[1]==='snack')return ['1 c. à café de miel, cacao ou cannelle selon tes goûts'];return ['1 gousse d’ail','1 c. à soupe d’huile','Sel, poivre et épices'];}
function recipeIngredientLines(recipe,omitted){if(Array.isArray(recipe._ingredients)&&recipe._ingredients.length)return recipe._ingredients;const main=recipeTags(recipe).filter(tag=>!omitted.includes(tag)).map(tag=>cookingAmounts[tag]).filter(Boolean);const extras=recipeFlavorLines(recipe,omitted);return [...new Set([...main,...extras,'Sel et poivre'])]}
function recipeCookingSteps(recipe,omitted){if(Array.isArray(recipe._steps)&&recipe._steps.length)return recipe._steps;const name=recipe[0].toLocaleLowerCase('fr'),tags=recipeTags(recipe).filter(tag=>!omitted.includes(tag)),has=tag=>tags.includes(tag),cold=/sandwich|wrap|bagel|panini|croque|toast|burger|tacos|pita|galette|salade|poké|bento|onigiri|taboulé/i.test(name),sweet=['breakfast','snack'].includes(recipe[1]),base=has('rice')?'Rince le riz puis fais-le cuire 10 à 12 min dans une casserole d’eau bouillante salée. Égoutte-le.':has('pasta')?'Porte une grande casserole d’eau salée à ébullition. Fais cuire les pâtes selon le paquet, puis garde une louche d’eau de cuisson.':has('noodles')?'Fais cuire les nouilles selon le paquet, puis égoutte-les et rince-les rapidement.':has('couscous')?'Verse la semoule dans un saladier, couvre d’eau bouillante salée, filme 5 min puis égrène à la fourchette.':has('quinoa')?'Rince le quinoa, couvre-le de deux fois son volume d’eau et laisse mijoter 12 min.':has('potato')?'Coupe les pommes de terre en petits dés puis fais-les cuire 12 à 15 min à la poêle couverte (ou à l’eau).':'Prépare une grande poêle ou casserole et mets tous les ingrédients à portée de main.';if(cold)return ['Lave et coupe les légumes. Si la recette contient une protéine crue, fais-la cuire à la poêle 5 à 7 min, puis laisse-la tiédir.',has('wrap')||/sandwich|bagel|panini|croque|toast|burger|tacos|pita|galette/.test(name)?'Tartine le pain ou les wraps avec la sauce. Ajoute la protéine, les légumes et le fromage, puis referme.':'Mélange la base, la protéine et les légumes dans un grand saladier. Ajoute la sauce seulement au moment de manger.',has('wrap')||/sandwich|bagel|panini|croque|toast|burger|tacos|pita|galette/.test(name)?'Pour un panini, croque ou quesadilla, fais dorer 3 min de chaque côté. Sinon emballe chaque portion séparément.':'Répartis dans les boîtes ; garde sauce et éléments croquants à part.', 'Laisse refroidir complètement avant de fermer les tuppers.'];if(sweet)return ['Sors les ingrédients et prépare 4 contenants ou bols.',has('oats')?'Mélange les flocons, le yaourt ou lait et les fruits. Laisse reposer au frais au moins 2 h.':has('eggs')?'Bats les œufs avec une pincée de sel, puis cuis-les à feu moyen jusqu’à ce qu’ils soient pris.':'Mélange les ingrédients dans un bol jusqu’à obtenir une préparation homogène.', 'Répartis en portions égales, laisse refroidir si besoin puis ferme.', 'Conserve au frais et prends une portion quand tu en as besoin.'];const veg=tags.filter(tag=>['onion','mushroom','broccoli','zucchini','tomato','pepper','carrot','spinach','greenbeans','eggplant','cauliflower','peas'].includes(tag)),protein=tags.find(tag=>['chicken','beef','pork','turkey','fish','tuna','salmon','shrimp','eggs','lentil','chickpea','beans','tofu'].includes(tag)),sauceStep=veg.length?'Ajoute les légumes, fais revenir 5 min puis verse la sauce. Laisse mijoter 3 à 5 min en remuant.':'Verse la sauce dans la poêle et laisse réduire 3 à 5 min en remuant.';return [base,`Pendant ce temps, coupe ${veg.length?'les légumes en petits morceaux':'les éventuels légumes'} et prépare la sauce / les épices.`,protein?`Dans une grande poêle chaude avec un peu d’huile, cuis ${foodLabelByTag[protein]||ingredientMap[protein]?.[0]||'la protéine'} : 5 à 7 min pour une viande en morceaux, jusqu’à cuisson complète.`:'Dans une grande poêle chaude avec un peu d’huile, fais revenir les aromates 2 min.',sauceStep,has('rice')||has('pasta')||has('noodles')||has('couscous')||has('quinoa')?`Mélange avec ${has('rice')?'le riz':has('pasta')?'les pâtes':has('noodles')?'les nouilles':has('couscous')?'la semoule':'le quinoa'} ou garde la base à côté. Goûte et rectifie sel/poivre.`:'Goûte, rectifie l’assaisonnement et coupe le feu.', 'Répartis dans 4 tuppers. Laisse refroidir 20 min avant de fermer ; garde 2 à 3 portions au frais et congèle le reste.']}
function openRecipeModal(recipe){if(!recipe)return;const source=recipeImage(recipe),fallback=recipeFallback(recipe),omitted=excludedOptionalTags(recipe),ingredients=recipeIngredientLines(recipe,omitted),steps=recipeCookingSteps(recipe,omitted),cold=/sandwich|wrap|bagel|panini|croque|salade|poké|bowl|bento|toast|onigiri|burger|tacos|galette/i.test(recipe[0]),sweet=['breakfast','snack'].includes(recipe[1]),storage=cold?'À consommer idéalement dans les 2 jours — ne pas congeler.':sweet?'Se garde en général 3 jours au frais.':'3 jours au frais ; congèle les portions prévues pour la fin de semaine.';recipeModal.innerHTML=`<div class="recipe-modal-card"><button class="recipe-modal-close" type="button" aria-label="Fermer">×</button><div class="recipe-modal-hero"><img src="${source}" onerror="this.onerror=null;this.src='${fallback}'" alt="${recipe[0]}"><div><span class="featured-label">🍳 Fiche recette · 4 portions</span><h2>${recipe[0]}</h2><p>${recipeSummary(recipe)}</p></div></div><div class="recipe-modal-body"><div class="recipe-modal-stats"><div class="recipe-modal-stat">⏱️ ~${recipeMinutes(recipe)} min</div><div class="recipe-modal-stat">🔥 ${recipe[3]} kcal<br><small>par portion</small></div><div class="recipe-modal-stat">💪 ${recipe[4]} g prot.<br><small>par portion</small></div></div><p class="recipe-modal-price">💶 ${recipePriceLabel(recipe)} · ${recipeEquipmentText(recipe)}</p>${omitted.length?`<p class="recipe-modal-adaptation">⚠️ Version proposée sans ${omitted.map(tag=>foodLabelByTag[tag]||tag).join(', ')} : cet ingrédient n’est pas essentiel ici.</p>`:''}<h3>Ingrédients <small>pour 4 portions</small></h3><ul class="recipe-ingredient-list">${ingredients.map(line=>`<li>${line}</li>`).join('')}</ul><h3>Préparation <small>dans cet ordre</small></h3><ol class="recipe-steps">${steps.map(step=>`<li>${step}</li>`).join('')}</ol><p class="recipe-modal-storage">🧊 <b>Conservation :</b> ${storage}</p></div></div>`;recipeModal.classList.remove('hidden');document.body.style.overflow='hidden';recipeModal.querySelector('.recipe-modal-close').onclick=closeRecipeModal}
function closeRecipeModal(){recipeModal.classList.add('hidden');document.body.style.overflow=''}
recipeModal.addEventListener('click',event=>{if(event.target===recipeModal)closeRecipeModal()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!recipeModal.classList.contains('hidden'))closeRecipeModal()});
const storeAliases={Lidl:['lidl'],'E.Leclerc':['leclerc','e.leclerc'],'Intermarché':['intermarché','intermarche'],'Carrefour':['carrefour']};
const localStoreAliases={Lidl:['lidl'], 'E.Leclerc':['leclerc'], Intermarché:['intermarché','intermarche'], Carrefour:['carrefour']};
async function fetchJson(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),6500);try{const response=await fetch(url,{...options,signal:controller.signal});if(!response.ok)throw new Error(String(response.status));return response.json()}finally{clearTimeout(timer)}}
async function resolveNearbyStore(){const postal=$('#postalCode')?.value.trim(),store=$('#store')?.value;if(!/^\d{5}$/.test(postal)||!store)return;const status=$('#localStoreStatus');status.textContent=`Recherche d’un ${store} autour de ${postal}…`;try{const geo=await fetchJson(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&country=France&postalcode=${encodeURIComponent(postal)}`,{headers:{'Accept-Language':'fr'}});if(!geo?.[0])throw new Error('postal');const {lat,lon}=geo[0];const query=`[out:json];nwr[\"shop\"=\"supermarket\"](around:10000,${lat},${lon});out center tags;`;const nearby=await fetchJson(`https://overpass-api.de/api/interpreter?data=${encodeURIComponent(query)}`);const aliases=localStoreAliases[store]||[];const hit=(nearby.elements||[]).find(place=>{const name=String(place.tags?.brand||place.tags?.name||'').toLocaleLowerCase('fr');return aliases.some(alias=>name.includes(alias))});if(!hit)throw new Error('store');window.localStoreOsmId=hit.id;window.localStoreName=hit.tags?.name||hit.tags?.brand||store;status.textContent=`📍 ${window.localStoreName} trouvé près de ${postal} : les relevés compatibles seront privilégiés.`}catch{window.localStoreOsmId=null;window.localStoreName=null;status.textContent=`Aucun magasin ${store} validé automatiquement près de ${postal} : moyenne estimée conservée.`}}
function packageGrams(value){const text=String(value||'').toLowerCase().replace(',','.');const kg=text.match(/(\d+(?:\.\d+)?)\s*kg/);const g=text.match(/(\d+(?:\.\d+)?)\s*g\b/);return kg?+kg[1]*1000:g?+g[1]:null}
function displayQuantity(item){return item.unit==='g'?Math.ceil(item.qty/10)*10:Math.ceil(item.qty)}
async function enrichWithOpenPrices(cart,store){const candidates=Object.values(cart).filter(item=>item.unit==='g').sort((a,b)=>b.price-a.price).slice(0,12);for(const item of candidates){try{const local=`${window.localStoreOsmId?`&location_osm_id=${window.localStoreOsmId}`:''}`;const url=`https://prices.openfoodfacts.org/api/v1/prices?product_name=${encodeURIComponent(item.name)}&size=30${local}`;const data=await fetchJson(url);const aliases=storeAliases[store]||[];const hit=(data.items||[]).filter(entry=>{const brand=String(entry.location?.osm_brand||entry.location?.brand||'').toLowerCase();const sameLocal=!window.localStoreOsmId||String(entry.location?.osm_id||entry.location?.id||'')===String(window.localStoreOsmId);return entry.currency==='EUR'&&Number(entry.price)>0&&sameLocal&&aliases.some(alias=>brand.includes(alias))}).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))[0];const grams=packageGrams(hit?.product?.quantity);if(!hit||!grams)continue;item.price=Math.ceil(item.qty/grams)*Number(hit.price);const price=document.getElementById(`${item.id}-price`),source=document.getElementById(`${item.id}-source`);if(price)price.textContent=`${item.price.toFixed(2).replace('.',',')} €`;if(source)source.textContent=`Relevé ${window.localStoreName||store} · ${hit.date||'date inconnue'}`;const total=Object.values(cart).reduce((sum,row)=>sum+row.price,0);const totalNode=document.getElementById('cart-total');if(totalNode)totalNode.textContent=`Total estimé : ${total.toFixed(2).replace('.',',')} €`}catch{/* prix moyen local conservé */}}}
function build(){
 const picked=recipes.filter(r=>selected.has(r[0]));
 const planned=portionPlan(picked);window.lastPortionPlan=planned.map(item=>({recipeName:item.recipe[0],portions:item.portions}));
 const factor={Lidl:.86,'E.Leclerc':.95,Intermarché:1,Carrefour:1.08}[$('#store').value];
 const cart={};
 planned.forEach(({recipe,portions})=>{const scale=portions/4;recipeTags(recipe).filter(tag=>!excludedOptionalTags(recipe).includes(tag)).forEach(tag=>{const item=ingredientMap[tag];if(!item)return;cart[item[0]]??={name:item[0],qty:0,unit:item[1]===6?'pièces':'g',price:0,aisle:aisleByTag[tag]||'Épicerie'};cart[item[0]].qty+=item[1]*scale;cart[item[0]].price+=item[2]*factor*scale})});
 const total=Object.values(cart).reduce((sum,item)=>sum+item.price,0);Object.values(cart).forEach((item,index)=>item.id=`cart-item-${index}`);window.lastPlanTotal=total;
 const aisles=Object.entries(cart).sort((a,b)=>a[1].aisle.localeCompare(b[1].aisle)||a[0].localeCompare(b[0])).reduce((groups,[name,item])=>{(groups[item.aisle]??=[]).push([name,item]);return groups},{});
 $('#schedule').innerHTML=`<p class="note">🍱 Prépare ces ${picked.length} recettes dimanche pour <b>${batchPortionCount()} tupperwares au total</b>. Les portions sont réparties selon ton choix, pas automatiquement par 4.</p>`+planned.map(({recipe,portions},i)=>{const fresh=Math.min(portions,i===0?Math.min(3,portions):1),frozen=Math.max(0,portions-fresh);return `<div class="day"><b>${recipe[0]} · ${portions} tupperware${portions>1?'s':''}</b><br>❄️ ${fresh} au frais · 🧊 ${frozen} au congélateur.${recipeGuide(recipe)}</div>`}).join('');
 $('#cart').innerHTML=Object.entries(aisles).map(([aisle,items])=>`<h3>🛒 ${aisle}</h3>${items.map(([name,item])=>`<div class="day">☐ ${name} · ${displayQuantity(item)} ${item.unit} <span id="${item.id}-price" class="price">${item.price.toFixed(2).replace('.',',')} €</span><small id="${item.id}-source">Moyenne estimée</small></div>`).join('')}`).join('')+`<p id="cart-total" class="total">Total estimé : ${total.toFixed(2).replace('.',',')} €</p><p>Relevés datés quand disponibles ; sinon moyenne estimée. À confirmer en magasin.</p><p>${total>+$('#budget').value?'⚠️ Dépasse ton budget : retire une recette ou sélectionne Lidl.':'✓ Dans ton budget.'}</p>`;
 void enrichWithOpenPrices(cart,$('#store').value);
 window.batchPlanReady=true;showScreen('final');
}
