function proteinTarget(){const weight=Number($('#weight').value);if(!weight)return '—';const factor=$('#goal').value==='gain'?1.55:$('#goal').value==='loss'?1.2:1.1;return Math.round(weight*factor/5)*5}
async function updateStats(){try{const state=await fetch('/api/me').then(res=>res.json());const plans=state.history||[],measurements=state.measurements||[];const spent=plans.reduce((sum,plan)=>sum+(+plan.estimatedTotal||0),0);const newest=measurements[0]?.weight,oldest=measurements.at(-1)?.weight;const delta=measurements.length>1?newest-oldest:0;const deltaText=Math.abs(delta)>=.05?` · ${delta<0?'−':'+'}${Math.abs(delta).toFixed(1)} kg`:'';const weightText=measurements.length?`${newest} kg${deltaText}`:'Pas encore de pesée';const goalLabel={loss:'Perte de poids',maintain:'Maintien',gain:'Prise de masse'}[$('#goal').value];$('#stats').innerHTML=`<article class="stat">${calorieTarget()} kcal<small>repère quotidien · ${goalLabel}</small></article><article class="stat">${proteinTarget()} g<small>protéines / jour · repère</small></article><article class="stat">${weightText}<small>ton suivi de poids</small><label>Nouvelle pesée (kg)<input id="weightEntry" type="number" min="30" max="350" step="0.1" placeholder="ex. 127,5"></label><button class="primary" onclick="saveWeight()">Enregistrer</button></article><article class="stat">${plans.length} batch${plans.length===1?'':'s'}<small>${spent.toFixed(2).replace('.',',')} € prévus au total</small></article>`}catch{$('#stats').innerHTML='<article class="stat">Suivi disponible dès ton premier batch.</article>'}}
window.saveWeight=async()=>{const value=$('#weightEntry')?.value;const weight=Number(String(value).replace(',','.'));if(!Number.isFinite(weight)||weight<30||weight>350){const entry=$('#weightEntry');if(entry){entry.focus();entry.placeholder='Entre 30 et 350 kg';}return}$('#weight').value=weight;const fields=[...profileFields,'sex','diet','postalCode'].filter(key=>$('#'+key));const profile={...Object.fromEntries(fields.map(key=>[key,$('#'+key).value])),equipment:selectedEquipment(),batchPortions:batchPortionCount()};localStorage.setItem('batch-profile',JSON.stringify(profile));await Promise.all([fetch('/api/me',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(profile)}),fetch('/api/measurements',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({weight})})]);updateStats()};
